#define R(p,a,r)mix(a*dot(p,a),p,cos(r))+sin(r)*cross(p,a)
#define H(h)(cos((h)*6.3+vec3(0,23,21))*.5+.5)
#define PI 3.141592
#define pal(x) (cos(x*2.*PI+vec3(0, 22, 14))*.5+.5)
#define SIN(x) (.5+.5*sin(x))
#define tt iTime*0.1
#define S(a, b, x) smoothstep(a, b, x)
#define rot2(x) (mat2(cos(x), sin(x), -sin(x), cos(x)))

#define samples 3

mat2 rot(float a) {
    float c = cos(a);
    float s = sin(a);
    return mat2(c, -s, s, c);
}

float x, y;
float cir1(vec2 p) {
    x=1000., y=1000.;
    for (float i=0.; i<7.; i++) {
        p=abs(p)/clamp(p.x*p.y,.3,5.)-1.;
        x=min(x,abs(p.x));
        y=min(y,abs(p.y));
    }
    x=exp(-.5*x);
    y=exp(-1.*y);
    return x-y*.1;
}

float cir2(vec2 p) {
    p.x-=1.5;
    float x=1000., y=1000.;
    for (float i=0.; i<5.; i++) {
        p=abs(p)/clamp(abs(p.x*p.y),.2,2.)-1.;
        x=min(x,abs(p.x));
        y=min(y,abs(p.y));
    }
    y=exp(-.7*y)-x*.1;
    return y;
}

float struc(vec3 p) {
    float d=length(p+vec3(0.,-3.,0.))+.6;
    d=min(d,length(p.xy+vec2(0.,-3.))+1.3);
    d=min(d,length(p.zy+vec2(0.,-3.))+1.5);
    vec2 s=sign(p.xz);
    p.xz=abs(p.xz);
    d=min(d,max(length(p.xz-5.-s*.5)+.5+p.y*.2,p.y-2.));
    return d;
}

float h;
float de(vec3 p) {
p.zy*=rot2(iTime*0.1);
    p.yz*=rot(1.1);
    p.xz*=rot(.0);


     p.zy*=rot2(iTime*0.01);
      p.xy*=rot2(iTime*0.21);
    float r1=cir1(p.xz*.35);
    float r2=cir2(p.yz*.15);
    float sup = p.y;
    float sph = struc(p);
    float d = min(sup, sph);
    h=r1*.01+r2*0.1;

    d-=h;
    return d*.5;
}

float det = 0.005;

vec3 normal(vec3 p) {

    vec2 e = vec2(0.0, det);
    return normalize(vec3(de(p + e.yxx), de(p + e.xyx), de(p + e.xxy)) - de(p));
}

vec3 march(vec3 from, vec3 dir) {
    from.xy*=5.;
    vec3 p = from, col = vec3(0.0);
    float d=0.;
    for (int i = 0; i < 100; i++) {
        p += d * dir;
        d = de(p);
        if (d < det) break;
    }
    if (d < det) {
        float cx=x,cy=y;
        vec3 n = normal(p);
        vec3 ldir = normalize(vec3(-1., 1., -1.0));
        float dif = smoothstep(.8,1.,max(0., dot(ldir, n)));
        dif+=smoothstep(.5,.8,max(0.,dot(-dir,n)))*.35;
        col = vec3(1.8,1.,.5)*dif;
        float shadow = 1.0;
        vec3 shadowRay = p + n * 0.01;  
        for (int i = 0; i < 30; i++) {
            float d = de(shadowRay);
            if (d < 0.005) {
                shadow = 0.0;  
                break;
            }
            shadowRay += ldir * d;  
        }
        col+=step(cx,.87)*vec3(0.,1.,1.)*.5;
        col*=.3+shadow*.7;
        col+=step(fract(cy*3.),.25)*vec3(1.,0.3,0.1);
    } 
    return col;
}


vec3 antialiasedMarch(vec3 from, vec3 dir) {
    vec3 color = vec3(0.0);  
    vec2 offsetScale = 2./iResolution.xy; 

    for (int i = 0; i < samples; i++) {
        for (int j = 0; j < samples; j++) {
            vec2 offset = vec2(float(i), float(j)) / float(samples) - 0.5;
            vec3 displacedFrom = from + vec3(offset* offsetScale, 0.0) ;
            color += march(displacedFrom, dir);  
        }
    }

    return color / float(samples * samples);  
}
void mainImage(out vec4 O, vec2 C)
{
    O=vec4(0);

      vec2 uv = (C-.5*iResolution.xy)/iResolution.y;;

      vec2 uv3 = (C- iResolution.xy * 0.5) / iResolution.y;

    vec3 from = vec3(uv3, -6.);
    vec3 dir = normalize(vec3(0.,0., 1.));

    vec3 col3 = antialiasedMarch(from, dir)+.05;
    col3*=exp(-3.*length(C/iResolution.xy-.5))*1.3+.2;

    vec3 p, rd = normalize(vec3(uv, 1.-.2*SIN(PI+.25*tt))), ro = vec3(0, 0, tt*.05);

    vec3 col = vec3(0);

    for(float i=0., s, d, t=0.; i < 100.; i++)  {

       p = t*rd + ro;

       float len = mix(.5*(abs(p.x) + abs(p.y)), length(p.xz), .4);


       p = abs(p) - vec3(.1+.02*S(3., 7., tt), .4-.02*S(3., 7., tt), 1.9);
       s = 2.7;

       for(int j; j < 5; j++) {
            p.xy *= mix(1.05, .95, SIN(length(p.xy)*.5+.1*tt));
            p = abs(p-vec3(1.2, 1.3, 1.1)) - vec3(1., 1.2, 1.08+0.04*sin(tt));

            s *= d = 2.5/clamp(dot(p, p), .5, 1.7);

            p = abs(p)*d;
        }      

        p.xy *= rot(.5*PI*SIN(tt));

        t += d=(max(length(p.xz), -(length(p-ro)-.3)))/s;
        col +=  mix(vec3(0.992,0.765,0.447), pal(log(s*.4+1.+tt)*.5), .7)*.02*exp(-.7*i*i*d);
    }

    vec3 n1,q,r=iResolution,
    d=normalize(vec3((C*2.-r.xy)/r.y,1));  
    for(float i=0.,a,s,e,g=0.;
        ++i<70.;
        O.xyz+=mix(vec3(0.1,0.2,3.),H(g*.1),.8)*1./e/8e3
    )
    {
        n1=g*d*col3;
      n1.xy*=rot2(iTime*0.1);
      n1.zy*=rot2(iTime*0.1);
n1.z+=iTime;


        a=30.;
        n1=mod(n1-a,a*2.)-a;
        s=3.;

        for(int i=0;i++<8;){
            n1=.3-abs(n1);
            n1.x<n1.z?n1=n1.zyx:n1;
            n1.z<n1.y?n1=n1.xzy:n1;
            s*=e=1.7+sin(iTime*.021)*.01;
            n1=abs(n1)*e-
                vec3(
                    5.*3.,
                    120,
                    8.*5.
                 );
         }
         g+=e=length(n1.yzzz)/s;
    }
    O*=vec4(col3*50.,1.);
}
